quests[51961] = { id = 51961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ongoing Campaign", description = "We have made excellent progress on Zandalar, {name}, but we must continue to expand our influence.\n\nIt is time for us to cross the sea once again to exert pressure on enemy lands, lest they fall fully into Horde hands.\n\nWhich location shall we secure next?", completion = "Excellent choice, {name}.", objectives = "Use the Zandalar Campaign Map to choose a foothold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51962] = { id = 51962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumbering Away", description = "The hardwoods in dis jungle are dense enough dat dey rival coal in terms of how much heat a skilled miner can get out of dem.\n\nThe biggest problem using local timbers, however, is dat de jungle is always wet. If de wood is not stored properly, it takes weeks to dry out entirely.\n\nI bring dis up because my forge is starting to run low on fuel.\n\nBring me some dry firewood to keep it going, and in exchange I will teach you a trick for mining monelite.", progress = "Have you got more wood for me?", completion = "Dis should do nicely.\n\nListen well for your reward: When you are mining monelite, do not just chip away at de rock. Instead, try using de pick to pierce de metal, and den peel all of it away from de rock.", objectives = "Collect 9 Pieces of Dry Firewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51963] = { id = 51963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of Vorrik" }
quests[51964] = { id = 51964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insufferable Bloodsuckers", description = "{name}! I have some actual work that you could do for me.\n\nSince your mining skills are still not what Zandalari consider \"decent\", in exchange, I will show you how to mine monelite better.\n\nDe blood trolls of Nazmir have dese enormous ticks that they keep as pets and I have heard dat dey have managed to get within de borders of Zuldazar to de north. Dis does not sit well with me.\n\nThin their numbers for me, so I can happily die by being eaten by a pterrordax or something else respectable instead.", completion = "Commendable effort, and you seem no worse for wear. I need to remember dis next time I need something exterminated.\n\nI doubt you have noticed that monelite is extremely maleable, ya? Otherwise I would not have to teach you dis method. But you can exploit its malleability, even before smelting it.\n\nBy using your pick to deform the metal while it is still in the vein, you can cause it to heat up and get a bigger haul using the other technique I taught you.", objectives = "Kill 8 Bloodbelly Flyers and 8 Blood Trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51965] = { id = 51965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lending a Hand", description = "If you are looking for some work, I have something you can do.\n\nI went mining recently and a diemetradon managed to bite off my hand before I could get away from it.\n\nI do not care about the hand, I have already regenerated dat, but I did lose a couple rings dat I made.\n\nIf you go get them back, I will show you how to harvest more monelite from a seam. Or not. I do not care, but if you were looking for a chance to finally impress me, dis could be it.", progress = "For de record, those rings are worth more den your life. Empirically speaking, of course.", completion = "<Secott places the rings on his new hand.>\n\nGood! As a goldsmith without jewelery, I was beginning to feel naked.\n\nVery well, your lesson is that when you are mining monelite from a seam, it behaves very differently than a normal deposit.\n\n<Secott spends as little time as necessary explaining the different techniques of mining monelite seams.>", objectives = "Retrieve Secott's Rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51967] = { id = 51967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Boralus", description = "I think that's enough excitement for today, <lad/lass>!\n\nWhy don't ya get back ta Wyrmbane and tell the man we've got this place all under control.\n\nI'll make sure the blood trolls don't get any more of our folk! Ha!", completion = "The lands of Nazmir are cruel to all who enter, but Fort Victory shall stand firm in the face of danger.\n\nWell done, {name}.", objectives = "Return to Halford Wyrmbane on the Wind's Redemption in Boralus Harbor. Desha Stormwallow can give you a ride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51968] = { id = 51968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Boralus", description = "You know, a lot has happened since you arrived in Zuldazar! I'm sure Mr. Wyrmbane would appreciate a report.\n\nOh, not from me. Maybe somebody a bit more serious... like you!\n\nI bet Daria over here could get you back pretty quick!", completion = "We'll base our operations out of Xibala, then. And I'll have some reinforcements sent out to assist Brigadier Thom.\n\nThank you for your report, {name}. Well done.", objectives = "Return to Halford Wyrmbane on the Wind's Redemption. Daria Smithson can give you a ride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51969] = { id = 51969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Boralus", description = "Shatterstone Harbor is an expansive foothold, and one that we will use to great advantage against the Horde.\n\nI will leave Umbric and the others in charge here. Let's get back to the Wind's Redemption and return to Boralus.", completion = "The waters outside Vol'dun are rough, but Jes-Tereth is one of the best helmsmen on the sea!\n\nLet us roll one victory into another.", objectives = "Return to Halford Wyrmbane on the Wind's Redemption in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51970] = { id = 51970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Caterer" }
quests[51971] = { id = 51971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exquisite Brooch", description = "You find a bloody brooch that features impeccable craftsmanship.\n\nThe design and quality of work reminds you of rings you previously recovered for Secott.\n\nPerhaps this is another item he lost and would like to see returned.", completion = "Wow, dis is a nice brooch. Good craftsmanship in it.\n\nWhoever it used to belong to, it is mine now.\n\n<Seeing the disapproval on your face, Secott sighs heavily while rolling his eyes and gives you a sidelong glance.>\n\nTell ya what, in exchange for dis, I guess I can tell you the rest there is to know about mining monelite seams.\n\n<Secott explains in depth, several techniques which will allow you to mine monelite from seams more effectively.>", objectives = "Bring the Exquisitely Crafted Brooch to Secott.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51972] = { id = 51972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Goat" }
quests[51974] = { id = 51974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabertron" }
quests[51975] = { id = 51975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Shadow Hunter Ty'jin", objectives = "You be impressin' me wit ya skills in parleyin', boss-mon.\n\nI tink da two of us should be stickin' togetha. Da spirits insist!\n\nDon't be worryin'. I'll get changed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
