quests[51979] = { id = 51979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ongoing Campaign", description = "The Warchief wishes for us to continue spreading our influence throughout Kul Tiras.\n\nWith our grip on Zandalar on the rise, now is the time to move forward with this objective in the lands of the enemy.\n\nWhich location shall we secure next, {class}?", completion = "You have made your choice.", objectives = "Use the Kul Tiras Campaign Map to choose a foothold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51980] = { id = 51980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Jabra'kan", description = "To any hunters worthy of the challenge:\n\nFind and defeat the troll known as Jabra'kan. His poaching ways have robbed Warbeast Kraal of valuable eggs, hides, and beasts for their pens.\n\nSeek out Wingrider Nivek for your reward.", progress = "If I see dat thieving wretch, I will wear his tusks for a necklace. Is it done?", completion = "You have my thanks. He was a slippery one, dat poacher.", objectives = "Slay Jabra'kan the Poacher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51981] = { id = 51981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earthcaller's Abode" }
quests[51982] = { id = 51982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm's Rage", description = "Horde forces are pushing deeper into Stormsong Valley. We can not allow this aggression to go unchecked!", progress = "We cannot rest until the people of Stormsong Valley are protected from the Horde!", completion = "You served the people of Stormsong Valley, and the Alliance, well today. Thank you, {name}. With persistence, we will drive the Horde from this land.", objectives = "Repel the Horde forces assaulting Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51983] = { id = 51983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorrik's Vengeance" }
quests[51984] = { id = 51984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Zuldazar", description = "Look at dis place, boss-mon! We got da pirates, a location close to da Kul Tiran capital...\n\nI tink we should be bein' pretty proud of dis one.\n\nWe should get goin' back and tell Nathanos about our success. Maybe we can even get him to crack a smile.", completion = "That's quite a location Ty'jin scoped out.\n\nThe pirates are another boon. If we ever need some bodies to fall on swords for us... they will do.", objectives = "Return to Nathanos Blightcaller on the Banshee's Wail. Erul Dawnbrook can give you a ride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51985] = { id = 51985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Zuldazar", description = "You know kid, I think I've got it all covered here. My guys will find all the Azerite they can here and make me rich!\n\nI mean, you know, make the Horde rich. With power!\n\nAnyway, you can go tell Nathanos we're done here. This base is the best place to launch any attacks against the Kul Tirans here in Drustvar -- that's a Gallywix guarantee!", completion = "You've established a foothold in Drustvar with the goblins? Good.\n\nI will have my men keep an eye on Gallywix's activities there. Just in case.", objectives = "Return to Nathanos Blightcaller on the Banshee's Wail. Swellthrasher in Anyport can give you a ride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51986] = { id = 51986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Zuldazar", description = "Warfang Hold is our most secured of the footholds we hold in Kul Tiras.\n\nKaga and her forces will be able to keep fortifications running, thanks to you. The Alliance will never see us coming!\n\nTell Nathanos that we have succeeded in our mission. I will help here until I am needed.", completion = "Warfang Hold is an important strategic base for the Horde.\n\nIt is imperative that it stays safe. Rexxar will see to that.", objectives = "Return to Nathanos Blightcaller on the Banshee's Wail. Muka Stormbreaker can give you a ride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51987] = { id = 51987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hobart Grapplehammer", objectives = "Now that everything's all set up around here, I'm out of work!\n\nI bet you're going to need a pretty handy engineer. Why don't you take me along with ya?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51988] = { id = 51988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitney \"Steelclaw\" Ramsay" }
quests[51989] = { id = 51989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braedan Whitewall" }
quests[51990] = { id = 51990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wings for the Kraal", description = "It seems your little one needs a moment to rest after dat adventure. I will look after it.\n\nIf you want to make yourself useful while you wait, I heard de pterrordaxes to de north have been laying lots of eggs recently. Go collect de ones dat are wiggling and making noises. Dey are about to hatch.\n\nOur beasts breed well, but we always need more wings for de kraal.", progress = "Do you have de eggs I asked for?", completion = "I will get dese to a handler. We should be de first thing dey see if we want to keep dem.", objectives = "Collect 8 Nearly-hatchling Pterrordax Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51991] = { id = 51991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charging the Batteries", description = "These little fellas are ravenous whirlwinds of devouring destruction. When they get going, they consume anything in their path, without even stopping! When sated, they discharge power from them little 'lectric zingers on their heads! \n\nThen they nap.\n\nLucky for us, we found just the right frequency to control their tiny bug brains. Hit that device, and you can take your own little zapper out for a spin... literally!\n\nMake sure ya bring it back full, so we can keep our rigs charged!", progress = "All juiced up?", completion = "Hey! Not bad for your first time! They're so ugly they're cute, aren't they?", objectives = "Fill that ranishu's belly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51995] = { id = 51995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorrik's Vengeance" }
quests[51996] = { id = 51996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earthcaller's Abode" }
quests[51997] = { id = 51997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thar She Sinks" }
quests[51998] = { id = 51998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DGH: Now With Real Direhorn", description = "...Listen, {name}. I need one more thing to finish making this supplement of mine.\n\nDirehorn Growth Hormone can't exactly be made without, you know, actual direhorn. But I floated the idea of harvesting a few of their beasts and all of a sudden I got a bunch of spears pointed at me.\n\nSo I came up with another plan.\n\nThose flying beasts eat direhorns, right? The big green flappy ones. I'm sure if you kill a few of them you'll find all the direhorn bits I need.", progress = "We'll keep this between you and me, okay?", completion = "Let's not talk about this ever again. Deal?", objectives = "Collect 8 Partially-Digested Direhorn Flesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52003] = { id = 52003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kelsey Steelspark", objectives = "You know {name}, I've been following your adventure for a while and I just think you're so cool!\n\nI was hoping that maybe I could tag along with you, maybe help you out? I'm not so good in a fight, but nobody can beat my mechanical skill!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52004] = { id = 52004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counter Intelligence" }
quests[52005] = { id = 52005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: The Wolf's Den", description = "<Your followers have sent a report regarding the assault on Wolf's Den.\n\nIt details that victory was hard-fought, but all of the bandits previously living in the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.>", progress = "Do you have news regarding the mission to Tiragarde Sound?", completion = "It seems the mission to create an additional foothold in Tiragarde Sound was a success. Well done, {name}.\n\nI will send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52006] = { id = 52006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preemptive Assault" }
quests[52007] = { id = 52007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engines of War" }
quests[52008] = { id = 52008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Magister Umbric", objectives = "I swear, sometimes I don't know how I end up in these situations!\n\nFirstly, there is nothing of interest to me here. Secondly, the heat is absolutely sweltering. I would have understood if I was requested to study the stone that the sethrak held... but alas.\n\nWould you take me out of here and let me get back to doing work of actual import?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52009] = { id = 52009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab People", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52010] = { id = 52010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tendrils of Fate" }
quests[52011] = { id = 52011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiendish Fields" }
quests[52012] = { id = 52012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolves For The Den", description = "Our scouts have spotted a large pack of dire wolves not far from here. This is a good omen!\n\nWe should send a beast master to capture the wolf pack and bring them to the outpost to be tamed.\n\nThe dire wolves will make fine hunting companions and sniff out any Alliance spies that come poking around!", completion = "Rexxar brought us a fine pack dire wolves, {name}. Our operation will be much more secure with the dire wolves patrolling the outpost!", objectives = "Complete the mission, \"Wolves For The Den.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52013] = { id = 52013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: John J. Keeshan", objectives = "Now that we've settled in here... I aim my sights higher.\n\nYou've dealt with Conrad. You've dealt with the blood trolls. What's next for you, I wonder?\n\nWhatever it is, I'm in. You're going to need a hardcore, experienced, tenacious combatant like me if you plan on winning this war!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52014] = { id = 52014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualistic Preparations", description = "I have received a request for a shipment of storm silver. It is a fine metal, lightweight and resistant to corrosion. We use it althroughout our ships. It is so strong even de naga use it in some of their weapons!\n\nHowever, any parts that go into de ship have to be blessed by a wavesinger. I can not be bothered with dat nonsense. I do not believe it needs these extra blessings, but what do I know?\n\nHarvest a bucketful of ore and get it blessed for me, and I will teach you how to mine it easier.", progress = "Did you get those storm silver bars? Don't forget dat it needs to be blessed. Otherwise dey are 'land metal' and will curse a ship.", completion = "Nice, dis looks good. Dey should not be able to tell dat I didn't gather it myself.\n\nThese bars will be used as part of our next warship. Well, after dey get gold plated.\n\nWhat? You did not think dat de ornaments were solid gold, did you?  Ha! Dat would cause dem to weigh tons!\n\nNow then, you scratched my back, and I will scratch yours. Storm silver is very brittle naturally. When you mine it, use several small swings instead of one big one. Dis keeps de metal from being chipped away.", objectives = "Mine Unsanctified Storm Silver Ore, smelt it into Unsanctified Storm Silver Bars, and get them blessed by Wavesinger De'zan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52015] = { id = 52015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brined Justice", description = "{name}, I just got word dat one of our ships was attacked and a large amount of storm silver stolen!\n\nDe sacred materials can not be replaced. Once it is blessed by de wavesinger, it is buried underwater for a year. While I do not care for such nonsense, others do, and will not sail on dat ship.\n\nFrom what I heard, a group of naga followed de ship to see where the metal was buried on de sea floor before killing de crew and taking her cargo.\n\nKill de naga, and get me dat metal!", progress = "Loa damn de naga!\n\nHave you found de bars?", completion = "Ah!  Dis is fantastic news! I will have someone run these out to da docks right away.\n\nI was starting to fear dat you might not make it. Not dat I care, I just did not want to have to explain myself twice.\n\nDat said, you have avenged my people.  In exchange, let me show you the finer points of harvesting storm silver.\n\n<Secott takes the next several minutes to explain what he knows about harvesting storm silver deposits.>", objectives = "Collect 100 Stolen Storm Silver Bars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52016] = { id = 52016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Sheets to the Wind", description = "You want to know more about storm silver?\n\nFine, if you are mining from a seam and make a mistake, you can make a deadly cloud of powderized metal. Now go.\n\n<After a moment Secott's face softens.>\n\nI am very busy, but if you insist on not dying, you should talk to my former apprentice, Biru. He is a drunk at Spirits Be With You, but he has some knowledge.\n\nTalk to Ximo, de Innkeeper, and buy him a drink. If he likes it, he'll talk, if not... well, I hope you have enough coin for more drinks.", progress = "<Secott's former apprentice, Biru, drunkenly stares at you.>\n\nWhadda you wan?", completion = "<Biru rambles almost incoherently, explaining the mechanics of mining storm silver from a seam>\n\n... and dat is how you... get de most of mining... Zzz...\n\n<As Biru drifts to sleep amidst a pungent cloud of brandy vapors, you think of the advice he provided.\n\nEager to experiment with your new mining technique, you leave the sleeping troll laying where he is.>", objectives = "Bring Biru The Drunk a drink he likes to learn his mining secrets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52017] = { id = 52017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Biru", description = "Oh, you are still here?\n\nWell, I wish I could help you but being de only goldsmith in de city of gold, I am unsurprisingly busy.\n\nI heard you had built a rapport with Biru. I'm sure he remembers more, if you're still looking for more information.\n\nAsk him if he can show you anything else. Tell him if he keeps you from bothering me for the rest of de day, I will stop sending fool hardy miners to him.", completion = "Secott sent you?\n\nWait... my old master? Dat Secott?", objectives = "Speak with Biru The Drunk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52023] = { id = 52023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informing the Horde", description = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, {name}. It was an honor fighting with you.", completion = "I shall inform the Dark Lady of your activities in Vol'dun at once. She will know how to best proceed against this  new threat.", objectives = "Speak with Baine Bloodhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52024] = { id = 52024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informing the Horde", description = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, {name}. It was an honor fighting with you.", sourceObjective = "Speak with Baine Bloodhoof.", sourceObjectiveStatus = "unverified-source-field" }
quests[52026] = { id = 52026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overseas Assassination", description = "Ready to go to war, {name}?\n\nMathias Shaw has assembled a list of priority Horde targets, and the first is an influential blood elf by the name of Arlethal Sunwatcher. Intelligence shows that he's the highest ranking member of the Reliquary, an elite blood elf excavation force.\n\nHe's just standing out in the middle of the desert in Vol'dun, practically begging to be assassinated. Shall we?", completion = "Here we are. Let's begin.", objectives = "Speak with Grand Admiral Jes-Tereth to sail to Vol'dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52027] = { id = 52027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vol'dun Plan", description = "Our target: Arlethal Sunwatcher, High Examiner of the Reliquary.\n\nBefore we charge off blindly into the dunes, however, I'd like to hold a quick strategy meeting with you and the others.", progress = "Let's talk strategy, {name}.", completion = "I admire Shandris's... directness.\n\nWe will proceed with both plans. Let's move.", objectives = "Discuss strategy with Halford Wyrmbane and Shandris Feathermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52028] = { id = 52028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Comb the Desert", description = "It's time to mobilize, then.\n\nI'll stick with you, {name}. Keep an eye out for Horde activity.", completion = "I don't think she's spotted us yet.", objectives = "Search Vol'dun for Horde activity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52029] = { id = 52029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Work", description = "That surveyor is wearing a Reliquary tabard. Sunwatcher must be hiring goblins to do his dirty work while he lounges somewhere in the shade.\n\n<Shandris nocks an arrow in her bow.>\n\nLet's find out what she knows.", progress = "What is that goblin up to?", completion = "<Halford looks over the Reliquary document you've obtained.>", objectives = "Slay Nazlara and find out what she knows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52030] = { id = 52030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Combing", description = "Guzbert will be busy planting explosives for a while. We should continue south, looking for more signs of the Horde.", completion = "Up there, by the ruins. You see them?", objectives = "Search for more signs of the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52031] = { id = 52031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic Reliquary", description = "Another goblin surveyor, and this one's reporting to a blood elf overseer of some sort. We're closing in on them, {name}.\n\nYou know the drill.", progress = "Sunwatcher will be ours soon.", completion = "A map! Perfect. This should give us all the information we need...", objectives = "Help Shandris assassinate Elisa Veilsong and Daxx Bombhand, then find out what they know.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52032] = { id = 52032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Stop Combing", description = "<Halford eyes the map one last time before folding it up.>\n\nOnward to the south, then.", completion = "We have an opportunity here, {name}. It would be a shame to pass it up.", objectives = "Continue searching for signs of the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52033] = { id = 52033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Rime Huntress", description = "The Waycrest Guard is offering a reward for any hunter who can track down and eliminate the Rime Huntress from the vicinity of Highroad Pass.\n\nTrack her with caution. She is a ferocious beast, and has been known to ambush even seasoned hunters.", completion = "So someone has finally managed to track down the Rime Huntress?  Now our traders can continue their routes to Tiragarde without fear of the beast.\n\nTake your reward, and my thanks.", objectives = "Defeat The Rime Huntress near Highroad Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52034] = { id = 52034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message to the Zandalari", description = "I know we're here to hunt the Horde, but this is an opportunity.\n\nExiles or not, these are Zandalari trolls, and the Zandalari have all but put in their lot with the Horde.\n\nLet's show them what we do to friends of the Horde.", completion = "I hope you left a few alive.\n\nThey need to learn to fear us.", objectives = "Slay 12 Zandalari Exiles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52035] = { id = 52035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improvised Survival", description = "The entirety of our copter's hold was reserved for bombs. There's actually still a lot of bombs left inside. Unfortunately, that meant that we weren't able to pack sufficient water and rations for our survival.\n\nDesert natives hoard supplies efficiently. I'm certain the Zandalari trolls up ahead wouldn't miss a few lost supplies.", progress = "<Halford nods sternly at you.>", completion = "Excellent reconnaissance. Well-done.\n\n<Halford begins distributing water and rations to the others in your group.>", objectives = "Gather 15 Zandalari Water Jugs and 15 Zandalari Rations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52036] = { id = 52036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Have Alpacas Here", description = "Did you see? Did you see them? The floofy alpacas?!\n\nI'VE ALWAYS WANTED A... I mean, ahh, ahem! I would like to acquire an alpaca. To study. For scientific reasons. Nothing to do with floofiness at all.\n\nHere, this should help you wrangle one back here.", progress = "So... floofy...", completion = "What a cutie. Look at her!\n\nLOOK AT HER.", objectives = "Use the Ultra-Safe Electrified Alpaca Lasso to obtain a Lost Alpaca, then bring it back to Explosioneer Zoidfuse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52038] = { id = 52038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitting Up", description = "<Halford looks over the map again.>\n\nThe final Reliquary digsite is southwest of here.\n\n{name}, you and Shandris are responsible for laying the explosives at the digsite. I'll work with Zoidfuse to establish a safe position to detonate from.", completion = "<Shandris licks her lips in anticipation.>", objectives = "Continue traveling southwest across the desert.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52039] = { id = 52039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delayed Deathification", description = "While we can handle the assassination portion on our own, I suppose there's no harm in distributing these gnomish bombs around the enemy's digsite.\n\nThey're designed to be detonated remotely, so try to bury them in the sand where they won't be noticed.", progress = "I hope you left them somewhere inconspicuous.", completion = "It's done? Good. Let's get a move on.", objectives = "Bury 8 Remote-Detonation Deathbombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52040] = { id = 52040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full of Arrows", description = "There's no need for Halford's overly-complicated desert explosion operation. We can take care of Arlethal Sunwatcher right here and now.\n\nHe's right over there. We can just... kill him.\n\nYou engage him. I'll join in when he least expects it. You ready?", progress = "Whenever you're ready, {name}.", completion = "Won't Halford be happy to find out that we've done his work for him?", objectives = "Slay Arlethal Sunwatcher with Shandris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52041] = { id = 52041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Wyrmbane", description = "Our work here is done. Halford and Zoidfuse should be further down the coast, to the east.\n\nIf you don't mind, I'll meet you there.", completion = "Arlethal is already dead?\n\nThat's good, I suppose... though it does take some of the fun out of my plan.", objectives = "Report to Halford Wyrmbane in Vol'dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52042] = { id = 52042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Boom", description = "Still, we've placed all those explosives, and there's nothing stopping us from detonating them and laying waste to the Horde's excavations.\n\nSpeak with Zoidfuse when you're ready, and we'll get this explosive gnome tech going!", progress = "Whenever you're ready.", completion = "Ha ha! That should set the Reliquary back a few months.", objectives = "Speak with Explosioneer Zoidfuse to initiate the Vol'dun Explosion Protocol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52043] = { id = 52043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of Grapes", description = "You look familiar. Do you owe me money? Wait... no, that's not it.\n\nIf you are here to learn, I could show you my secret mining technique, bu- Ugh...\n\nI am currently busy trying to see straight right now, amongst other things. Ugh... it feels like someone is swinging a pick at my skull. \n\nDe best cure for a hangover is pickle juice and a big greasy breakfast.\n\nTell you what, get me those things, preferably quickly and quietly, and I will teach you whatever want.", progress = "Dese shadows are loud. Can you fix dat, too?", completion = "Dis is just what I needed.\n\n<Biru spends several moments shoveling food into his mouth.>\n\nMmm... Right! If I recall correctly, you were asking about de storm silver seams?\n\nLet me tell you my secret technique, not even Secott knows. De metal is prone to stress fractures, but instead of scoring de metal where it meets de rock and breaking it off, just remove de rock.\n\nThe metal naturally forms prisms, and can be easily pulled out of the stone without wasting anything once it is loosened up.", objectives = "Bring a Jar of Pickle Juice, a Mountain of Bacon, a Pile of Sausages, and a Hillock of Eggs to Biru The Drunk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52044] = { id = 52044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exceptional Platinum Shard", description = "Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks.\n\nYou wonder to yourself if Myra could teach you to harvest this much every time.", completion = "Oh, wow! This is really impressive. You managed to get a decently sized shard of platinum in a single piece.\n\nIt looks like you managed to hit the ore in line with it's strata... Think of it like chopping wood with the grain, instead of against it.\n\nYou know, I bet if you sacrificed some of the power of your swing to keep the pick in line with the strata, you could probably get chunks this size all the time!", objectives = "Bring the Exceptional Platinum Shard to Myra Cabot.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52045] = { id = 52045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boarder Patrol" }
quests[52046] = { id = 52046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exceptional Platinum Shard", description = "Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks.\n\nYou wonder to yourself if Secott could teach you to harvest this much every time.", completion = "Hey, dis is actually pretty impressive. A decently sized shard of platinum in a single piece.\n\nI can only assume dat dis was done unintentionally?\n\nLet me save us both some time, I will tell you everything I know about platinum. If you have any further questions, take dem to someone else.\n\nDe ore forms with striations, like de grain in wood. Keep your pick aligned with de strata when you swing and it will keep de chunks intact, instead of breaking apart.", objectives = "Bring the Exceptional Platinum Shard to Secott the Goldsmith.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52047] = { id = 52047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Storm" }
quests[52049] = { id = 52049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X Marks the Plat!", description = "You find a folded piece of aged paper next to the deposit\n\nOpening it up, you find a map of Drustvar with an X along the western coast.\n\nSeveral crude poems adorn the paper, with one in particular drawing your attention.\n\n\"Once I were a pirate,\nlivin' for rum and pleasure.\nSince the mutiny, I've retired,\nan' now I mine for treasure.\"\n\nWhoever left this appears to have spent a significant time mining in these lands. They may have some insights you could benefit from.", completion = "<Seeing the map, Cinderfuse puts down her weapon.>\n\nI see ye found me map. Guess that means ye be a miner, too?\n\nWell then, if yer lookin' fer booty, best bet would be ta check yer breeches. However, if ye lookin' fer work, then I got just the task fer ya.", objectives = "Find the Tattered Map's maker in Drustvar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52050] = { id = 52050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A More Challenging Career", description = "As ye can imagine, piratin' be in me blood. Spent many of the best years of me life lootin' and plunderin'.\n\nMe favorite part was when takin' a chest filled ta the brim with gold and jewels, and buryin' it where only ye know.\n\nAlas, that life be too chaotic for me nowadays. Swashbucklin' makes me tired, and grog makes me sick. But... I can still bury me treasure.\n\nBring me some booty worth buryin', and I'll teach ya everythin' I've learned about minin' over the years.\n\nSo, wanna be me scallywag?", progress = "The winds be fine for adventure!", completion = "A fine haul! Pull up a crate, and grab a tankard of rum! This story be a long one!\n\n<Over many drinks, Cinderfuse regales you with many a humorous and informative tale, including several about mining platinum.>", objectives = "Collect 20 Platinum Nuggets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52051] = { id = 52051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Raid Finder - 1st" }
quests[52052] = { id = 52052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Raid Finder - Nth" }
quests[52053] = { id = 52053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Platinum Map", description = "Nestled within the fissures of the deposit, you find a small disc of pure platinum.\n\nDusting it off, you see etchings in its surface and recognize it as a map of Vol'dun. You also notice what appears to be a small cave in the south west that has been circled.\n\nWhoever left this apparently has a wealth of knowledge of the metal and wants to be found.", completion = "It is good to meet you. My name is Ta'mil. Please, take a seat, we have much to discuss.\n\nA long time ago, I used to be a miner and a shaman.\n\nI would tell de spirits what metals I needed and why I needed it, and ask them for what dey could spare. Dey would bring what dey could to de surface for me.\n\n<The warmth from his voice leaves as his face turns somber.>\n\nNow de spirits tell me I am not long for dis world. Even in dis desert, I feel de cold creeping into my bones.", objectives = "Find the Platinum Map's maker in Vol'dun.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52054] = { id = 52054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Much To Bear" }
quests[52055] = { id = 52055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ore for an Eye", description = "I have one last request before I can go.\n\nI wish to see de sunset one last time. I have an enchantment in mind, and I have all the materials I need except de metal.\n\nI need you to bring me twenty platinum nuggets.\n\nI have asked de spirits to bring me de ore, but dey do not listen to me anymore. Dat is why I hid de map where only someone who could be of help would find it.\n\nIf you help me out, I will teach you what I can about mining platinum.", progress = "De elements beckon me. Do you have de platinum nuggets?", completion = "Excellent!\n\n<Ta'mil mutters an incantation under his breath as he cradles the platinum nuggets in his hands. A bright light bursts out from between his fingers, fading away as he finishes. Turning to you, he smiles as he holds out what looks like a pair of platinum eyeballs.>\n\nI see you. I thank you for dis. I suppose dis means de next sunset will be my last.\n\nAs for your training...\n\n<Ta'mil picks up a large chunk of rock with platinum veins, and shows you his secrets to harvesting the metal.>", objectives = "Collect 20 Platinum Nuggets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52056] = { id = 52056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tendrils of Fate" }
quests[52057] = { id = 52057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Storm" }
quests[52058] = { id = 52058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Short-Lived Peace", description = "{name},\n\nAs the Legion's presence wanes from our world, a new threat has risen. It is with a heavy heart that I must ask you to put your life on the line for the Alliance once more. \n\nI have received a disturbing message from our operatives stationed in Orgrimmar.\n\nI await your arrival at Stormwind Keep to discuss matters further.", completion = "You have fought bravely in the name of the Alliance time and time again. For that, I owe you a great debt of gratitude.\n\nBut even more must be asked, I fear.", objectives = "Report to King Anduin Wrynn in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52059] = { id = 52059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thar She Sinks" }
quests[52060] = { id = 52060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Uprising", description = "Given the potential of Azerite to change the face of warfare, it comes as no surprise that the Warchief seeks to lay claim to it. Reports indicate that she is mobilizing an army to march on Silithus--the site of the great wound.\n\nHeroes of the Horde and the Alliance fought side-by-side during the Argus campaign. To think that Sylvanas is ready to cast that unity aside...\n\nSpeak with Mathias Shaw. I want you to oversee our presence in Silithus.", completion = "Wait! Our reports were wrong!", objectives = "Report to Master Mathias Shaw for further instruction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52061] = { id = 52061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taptaf the Pig!", objectives = "Taptaf looks up at you wide-eyed, after seeing his previous master slain. He seems eager to follow you now.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52062] = { id = 52062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disturbance in Ashenvale", description = "The damned Horde! Clever bastards, I'll give them that. They diverted at the north fork of the Barrens and are now marching on Ashenvale.\n\nThe kaldorei forces already set sail for Silithus--must be halfway there by now. The only defenders still in the area are the Darnassian City Guard. They are en route to Astranaar, but they won't last long against an army. Their commander goes by the name of Delaryn Summermoon.\n\nFind her, {name}, and buy us time. We will get our fleet there as soon as we can.", completion = "Are you the one Malfurion sent?", objectives = "Report to Captain Delaryn Summermoon in Astranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52063] = { id = 52063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boarder Patrol" }
quests[52064] = { id = 52064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiendish Fields" }
quests[52065] = { id = 52065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worse Than It Looks", description = "As bad as things are here we're managing to hold on.\n\nThings are actually a lot worse at Beacon Hill.  They're closer to the main attack, and will need all the help they can get.\n\nHead there and see if you can help.", completion = "Patrick's a good person.  If he trusts you, your help is welcome.", objectives = "Speak to Felicia Gladstone at Beacon Hill", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52067] = { id = 52067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survivors", description = "Patrick and Daryl Eckhart have a place north of town. If I know them, they'll be taking in survivors from Brennadam.\n\nCheck in with Patrick and see if they need any help.", completion = "Calvin sent you? We can use all the help you can provide!", objectives = "Speak to Patrick Eckhart at the Eckhart Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52068] = { id = 52068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping Out, Somewhere Else", description = "You've been a big help and now we've got a lot of gold to divvy up!   \n\nYou should go west to Seabreeze Village. Treat it like a vacation, keep your mind off the gold. We'll be fine here. When you come back later, we'll have your share all ready for you.\n\nYou'd just be getting in the way here.", completion = "Did he owe you any money? He always sends me people he owes money to!", objectives = "Speak to Lieutenant Bauer at Seabreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52069] = { id = 52069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Fodder", description = "Leo Shealds at Deadwash is a crook, but he recognizes the threat the naga pose. He'll send men to help us if we ask, even if most are just fodder.\n\nTravel to Deadwash and ask for help.", completion = "The way the Irontide's hitting us, there should be plenty of volunteers to go help.", objectives = "Speak to Leo Shealds at Deadwash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52070] = { id = 52070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauer Backup", description = "We've not heard anything from the coast since the Horde attack started. I need you to check in on Lieutenant Bauer at Seabreeze Village and see that they're safe.", completion = "Glad to hear Felecia is safe.  We could use your help here though.", objectives = "Speak to Lieutenant Bauer at Seabreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52071] = { id = 52071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Briarback Mountain" }
quests[52072] = { id = 52072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light of Elune", description = "My sisters lie slain on the soft earth of Ashenvale.\n\nWe are trained to expect losses. Soldiers die in battle. But this... this was a despicable attack, even for the Horde.\n\nWe have little time to grieve, but we are not savages like our enemy.\n\nPlease, {name}. Help me say a prayer to Elune in honor of the fallen. Their wisps deserve the light of her blessing.", completion = "Elune bless you, {name}.", objectives = "Honor the bodies of the fallen soldiers in Astranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52073] = { id = 52073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Petitioning Krag'wa", description = "Nothing! I cannot believe de weapon had no effect!\n\nDamn Ateena and her dark magic! We must get up there somehow, kill her for good, and remove dat barrier!\n\nBut how can we get to de top of dat building... ah, of course! Krag'wa! \n\nDe loa of frogs hates de blood trolls. I am sure he will lend us his aid. Then, finally, we will be able to put an end to Ateena's madness.", completion = "This is it, no more running around! \n\nNow, we will end this threat to my homeland once and for all!", objectives = "Summon Krag'wa to ask for his help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52074] = { id = 52074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliverance", description = "Mainlander! Stop a moment, I could really use a hand!\n\nMy team and I were hunting in the ruins of Gol Koval when the stones began to attack us! I've never seen anything like that before. Ranger Wons sent Duke and I to get some medical supplies for our injured.\n\nDuke didn't get hit by those possessed stone monsters but he wasn't as fortunate with the spiders nearby. He'll be okay if he rests here for awhile, but my team needs these medical supplies!\n\nPlease take these to Ranger Wons!", completion = "Rebecca sent you? Bless that girl! You've come just in time.", objectives = "Bring supplies to Ranger Encampment in Gol Koval.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52075] = { id = 52075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boned", description = "If the living rocks weren't bad enough, it seems the undead are hauling themselves out of the ground, too!\n\nThis used to be a Drust settlement, so those are probably Drust bones. They hated us and the feeling is definitely mutual right now.\n\nI don't know what has them stirred up, but they're a danger to us and everyone else. Take them out and I'll reward you for the work.", completion = "Hopefully those monsters will stay down. You have my thanks.", objectives = "Defeat 8 Vengeful Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52113] = { id = 52113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol'jin, Son of Sen'jin", description = "Even in da Echo Isles we have heard of da traditions of da Golden Road.\n\nWe must walk in da presence of royalty and hail da accomplishments of Vol'jin so dat his spirit be welcome here amongst da ancient kings.\n\nI shall carry da ashes, if you light da fires.\n\nKnow that any member of any other tribe may contest us. As our champion, we will need you to fend them off if they do.", completion = "Vol'jin. I must admit, I am impressed with his deeds. Had we met in dis world, I am sure he and I would have had much in common.", objectives = "Escort Vol'jin's Ashes to Atal'Dazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52114] = { id = 52114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honoring a True Leader", description = "Vol'jin. I have often felt our old chieftain's spirit whisperin' to me. His strength was da lifeblood of da Darkspear tribe. Some would even say he was da spirit of da true Horde.\n\nPrincess Talanji's offer is a great one. I shall travel with Vol'jin's ashes to Atal'Dazar.\n\nIf ya be wishin' to join us for dis procession, meet us upon da famed Golden Road.", completion = "Da power here... it be in da very earth. Da spirits be strong and ancient in dis land.", objectives = "Meet Master Gadrin at the Golden Road in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52115] = { id = 52115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Shadow of the Kraken" }
quests[52116] = { id = 52116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Soft Glow", description = "The wisps... they sing with sorrow, but also with purpose. The forest stirs, aglow with their light.\n\nThat sound... in the distance. Could it be our Shan'do?\n\nQuickly, {name}! Malfurion beckons!", completion = "I am glad you have come, {name}.", objectives = "Find Malfurion in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52117] = { id = 52117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Briarback Mountain" }
quests[52118] = { id = 52118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Out the Competition", description = "I've never cared much for battle, but I'll be damned if those fiends think they're gettin' this mill.\n\nBest if we clear the area quickly. Grab an axe and show me what you got.", progress = "What're you waiting for?", completion = "You're a natural.", objectives = "Pick up a Sturdy Axe, then gather 5 Freshly-Chopped Wood from the nearby Sapling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52119] = { id = 52119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Azerite Extraction", objectives = "Use the Goat Shears on 1 Gentle Goats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52120] = { id = 52120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomish Azerite Extraction", objectives = "Use the Goat Shears on 1 Gentle Goats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52122] = { id = 52122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Be Forsaken", description = "Let's move. Zelling is probably with his family now.\n\nEither they're happily reunited and he helps us find Valentine... or he just helps us find Valentine.\n\nLet's go.", completion = "Excellent work. I was wondering why Kyra was summoned away. Lucky for Lilian it was for a worthy cause.\n\nOur new ally is getting acclimated to his new life. We'll soon be ready to find Marshal Valentine.", objectives = "Go with Lilian Voss to find Thomas Zelling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52124] = { id = 52124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losers Weepers" }
quests[52126] = { id = 52126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Little Piggy Has Sharp Tusks", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52127] = { id = 52127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wolf's Den", description = "The raid you planned on Wolf's Den in Tiragarde Sound was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Wolf's Den in Tiragarde Sound and establish fortifications there.\n\nWolf's Den will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", completion = "Throm-Ka, {name}. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Tiragarde Sound!", objectives = "Claim Wolf's Den for the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52128] = { id = 52128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ferry Pass", description = "<Cyrus takes an official looking document from his jacket, signs it, then offers it to you.>\n\nHere, this will give you access to the ferry system.", completion = "There are ferry stations all along the interior coastline of the sound. Don't forget about them during your travels!", objectives = "Speak with Cyrus Crestfall and receive the Ferry Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52129] = { id = 52129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Problems", description = "Rozzy, part of the extraction crew, headed out with some gear to work on a plan to keep these reconfigulators all charged up.\n\nGo see see if she could use some help!", completion = "If Merd wants you to help, I've got just the thing!", objectives = "Check in with Rozzy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52130] = { id = 52130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadliest Cache: Carpe Diem", description = "Bah, don't listen to these landlubbers. They haven't fished an honest day in their lives!\n\nBefore they met me they were as dry as the sands o' the shoreline at low tide.\n\nI'll spin ye the tale o' the day we met. 'Twas also the day I saved the wharf from the biggest, meanest, largest monster o' the briny deep ye could imagine!", progress = "These landlubbers owe me their lives, if ye ask me!", completion = "Quite the story, eh lad?! Make sure ye tell yer friends!", objectives = "Listen to Coxswain Hook's tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52131] = { id = 52131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need Each Other", description = "My father believes he is indulging me. He has ruled for two hundred years, many lifetimes of trolls. In his mind, de threats dat face our kingdom are minor.\n\nI have seen too much to believe dat.\n\nSo since my father and his advisors would not help, I turned to someone who would.\n\nYour warchief needs our fleet, and I need her champions. So here is what we need to do.", completion = "Make your choice when you are ready.", objectives = "Listen to Princess Talanji.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52132] = { id = 52132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Proof of Piracy", description = "One thing pirates love more than gold is rum. So we're going to find their rum stashes and blow them up. With the rum all gone, a lot of the pirates should move on.\n\nUse my special barrel busting bombs to destroy the pirates' hidden rum stashes.", progress = "Let's blow up some rum!", completion = "That was hard, but it had to be done.", objectives = "Destroy 6 pirate Rum Stashes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52133] = { id = 52133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Boy!" }
quests[52139] = { id = 52139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Matters at Hand", description = "Princess Talanji should be ready to speak with you regarding how to save our empire.\n\nI would go speak with her now. She has a planning area set up nearby.", completion = "Good, you have returned. Dere is no time to waste.", objectives = "Speak with Princess Talanji within the Great Seal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52140] = { id = 52140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thorny Problem" }
quests[52142] = { id = 52142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restocking" }
