quests[52144] = { id = 52144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foundry Meltdown", objectives = "Slay 10 Company Watchmen, Company Enforcers, or Company Fusiliers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52145] = { id = 52145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heave-Ho!" }
quests[52146] = { id = 52146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood on the Sand", description = "And with that, our mission is done.\n\nLet's verify that Guzbert and Kelsey return safely from their demo sites, and then we can head back to friendlier shores.", progress = "Shouldn't be long now!", completion = "Guzbert's... what? No!", objectives = "Wait for Guzbert Gizmoflank and Kelsey Steelspark to return.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52147] = { id = 52147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crippling the Horde", description = "Our scouts report that one of Sylvanas's dark ranger captains is in Nazmir. \n\nThe dark rangers are Sylvanas's deadliest fighters and scouts. Killing one of their leaders will cripple Horde operations.\n\nShandris Feathermoon will be leading the operation in Nazmir. Head there now and strike before we lose this chance.", completion = "Nazmir. Let's be done with this place.", objectives = "Speak with Grand Admiral Jes-Tereth to sail to Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52148] = { id = 52148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freehold: A Pirate's End", description = "Hey, uh, I don't usually ask for help with personal business, but I know when I'm outmatched.\n\nSomeone's gotta take down Harlan.\n\nHe's a maniac. The things I saw him do back in the day... that's why I left Freehold in the first place.\n\nH-hey don't think of it as a favor for me--even though it would be a HUGE favor--think of it as making the seas safer for everyone, or something noble like that.\n\n<Flynn leans in and whispers.>\n\nPlus there's a big fat bounty on his head!", progress = "What's say sixty-forty split on the bounty? Eh? \n\nSeventy-thirty?\n\nHow about a finder's fee?", completion = "Gotta admit, when I first saw you in that prison cell I wasn't sure what all the fuss was about.\n\nBut you really came through for me. You came through for everyone.\n\nThanks, mate.", objectives = "Slay Harlan Sweete in the Freehold dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52149] = { id = 52149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everburning", description = "My people have suffered loss and pain, struggling in the darkness that covered Drustvar. But now we have some light back. We have the means and the will to reclaim our lands from the lingering evils. Your help has brought much of that about.\n\nI will miss my parents. Though their end was dark, they were family. But my duty as the head of House Waycrest is clear. The dead can handle themselves. I must attend to the living and lead.\n\nThere is a short ceremony I need to conduct. Would you assist me?", progress = "Thank you.", completion = "I must continue to set my House in order, but our relations with the rest of Kul Tiras have suffered neglect for too long. I have some additional things to handle here first, but I will go to Boralus soon to set the rest right.\n\nMy deepest thanks for all you have done, {name}.", objectives = "Assist in the ceremony by the statue in Arom's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52150] = { id = 52150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Kill a Dark Ranger", description = "Let's go over the plan. We don't get many chances to kill a captain of Sylvanas's dark rangers.", progress = "Well? Let's go over the plan.", completion = "We have our plan. Let's get underway.", objectives = "Listen to Shandris Feathermoon's plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52151] = { id = 52151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nation United", completion = "Hero, you have brought my family and my country back together again.\n\nMy heart is whole for the first time in many years.\n\nI cannot thank you enough.", objectives = "Attend the council meeting at Unity Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52153] = { id = 52153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege of Boralus: Lady Ashvane's Return", description = "If Ashvane thinks we will sit idly by as she attempts a coup, she is sorely mistaken.  The citizens of Boralus will fight her to a man.\n\nI'll need you on the front lines to aid them, {class}. Go with Taelia to the docks and engage the enemy. \n\nWith a little luck, we may just make it out of this alive.", completion = "That was incredible! I had no idea Lady Jaina was so powerful.", objectives = "Complete the Siege of Boralus dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52154] = { id = 52154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Next Target", completion = "I'm grateful for Alleria's wisdom and our new allies' willingness to take the lead. This new two-pronged strategy opens up additional tactical options for us to consider.\n\nI must ask Alleria to stay behind with me to coordinate our efforts on both ends. I'll need you to join Umbric on this mission and ensure its success. Good luck.", objectives = "Listen to the Alliance leadership debate the plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52155] = { id = 52155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure in the Tides", objectives = "Loot 8 Shipwreck Supplies in the Wailing Tideway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52156] = { id = 52156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollans in Distress", description = "Our first task is to rescue the tortollans captured by the blood trolls. \n\nKeeshan's report indicates the tortollans are familiar with all things Nazmir. They should know about the Horde's operations here.\n\nThe tortollans tend to stay neutral in most matters. They'll give us details on the Horde's plans if we make a fair trade.\n\nWe'll meet afterwards at our other outpost, Redfield's Watch, north of Torga's Rest.", progress = "What else do you need to know?", completion = "We've the information we need from the tortollans. We have to push on, time is of the essence.", objectives = "Rescue 6 Tortollan Captives from the blood trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52157] = { id = 52157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Chilling Encounter" }
quests[52158] = { id = 52158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savage Hunt", description = "The blood trolls in Nazmir are monsters, pure and simple. No culture, no empathy, they only exist to destroy.\n\nLet's kill 'em and let whatever dark god they worship sort them out.", progress = "The only good blood troll is a dead blood troll. And even that's stretching it.", completion = "We've been fending off blood troll attacks on Fort Victory for too long. Good to know they got what's coming to them.", objectives = "Kill 15 blood trolls and their allies within Torga's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52159] = { id = 52159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swab This!" }
quests[52160] = { id = 52160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restocking" }
quests[52163] = { id = 52163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Winged Typhoon", description = "NYI - Parrot poop bombing run" }
quests[52164] = { id = 52164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rum- Paaaage!" }
quests[52165] = { id = 52165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Automated Chaos", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52166] = { id = 52166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Faceless Herald" }
quests[52167] = { id = 52167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hardcore Raiders" }
quests[52168] = { id = 52168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Lit" }
quests[52169] = { id = 52169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Matriarch" }
quests[52170] = { id = 52170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending Areiel", description = "The tortollans have given us Captain Areiel's location, as well as new information. She carries a missive from the Horde.\n\nAny missive the Horde would send to Areiel must be extremely important. We must recover it and deliver the information to Halford.\n\nAreiel and I once fought side by side. She's incredibly powerful, Keeshan and I will be there to help you bring her down.\n\nGood luck, {name}.", progress = "Did you retrieve the missive?", completion = "I know I shouldn't take pleasure in Areiel's death... but there is a part of me that is glad her reign of terror is over.\n\nWhat of the missive?", objectives = "Recover the Horde Missive from Captain Areiel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52171] = { id = 52171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Option: Fire", description = "Here I thought things couldn't get worse, but now we have the Horde making camp around the home of some death god.\n\nI've got a good idea of what they've brought, thanks to my time in the first three wars. Medicine, armor, food...\n\nAnd probably offerings for this Bwonsamdi fella. Destroy all of these supplies to let the Horde know we won't let them stay here.", completion = "The Horde will be forced to retreat from the Necropolis without their supplies. A good win for us.", objectives = "Burn Bwonsamdi Offerings, Armory Supplies, Food Cache, and Medicinal Supplies in the Necropolis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52172] = { id = 52172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Can't Stay Here", description = "Can't believe the Horde already have a foothold in the Necropolis. We have to stop them.\n\nThis one's simple. Kill as many Horde as you find in that cursed place, but keep your eye out for a fella named Bwonsamdi.\n\nSeems like he's some sort of death god. He's way beyond anything we can handle, but why not send a few of his followers his way?\n\nBetter they rot in his necropolis than bother the living.", completion = "Good, less Horde for us to deal with in this cursed place.", objectives = "Kill 12 Horde soldiers within the Necropolis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52173] = { id = 52173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Void Elves Stand Ready", completion = "My trackers have already scouted the area and prepared a full report for us. You and I may begin our phase of the mission immediately.", objectives = "Speak with Grand Admiral Jes-Tereth and travel to Xibala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52174] = { id = 52174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snakes in the Shallows" }
quests[52179] = { id = 52179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortified Resistance" }
quests[52180] = { id = 52180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brennadam Shame" }
quests[52181] = { id = 52181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke and Shadow" }
quests[52182] = { id = 52182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azerite Stuff" }
quests[52183] = { id = 52183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When a Plan Comes Together", description = "Having Derek Proudmoore's body in our possession is a greater boon than we had planned for.\n\nValentine is risen, but I think it best to allow Derek to lay dead for a bit longer.\n\nIt's time to use our new allies to our advantage.", completion = "And now, we wait.", objectives = "Listen to Nathanos' plan, then travel to Plunder Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52184] = { id = 52184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of Ritual", description = "There is a reason why I am accompanying you on this mission, and it's more than familiarity. The Abyssal Scepter is locked behind a ritual, the components for which are held by three separate lieutenants spread across the compound.\n\nYou get the relics, I perform the ritual, we grab the Scepter and we get out.", progress = "Have you collected the relics yet?", completion = "Please do not tell me who you had to get through to obtain these relics. I do not want to know.", objectives = "Collect the Compass of Clarity, the Curio of the Depths, and the Key of the Sea in Stormsong Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52185] = { id = 52185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Well Placed Portal", description = "We have the front here under control. I am sending you and Zelling into Boralus to acquire the Abyssal Scepter.\n\nOculeth has managed to pinpoint a safe location for a portal. Get moving.", completion = "I once studied here. And now...\n\n<Zelling clears his throat.>\n\nWe have a job to do.", objectives = "Use the Portal to Boralus and meet with Thomas Zelling in Stormsong Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52186] = { id = 52186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bulk of the Guard", description = "If all has gone according to plan, Proudmoore has sent her elite forces to recapture her son's body.\n\nLet's make sure they stay out of the way of our real mission, hmm?", progress = "Oh, Katherine. You play right into our trap.", completion = "It's almost as if I could hear their screams from here.", objectives = "Kill 12 Proudmoore Guard on The Siren's Daughter and The Valorous Rose.\n\nHobart Grapplehammer can fly you out to the ships.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52188] = { id = 52188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tidesage Teachings", description = "These people are not tidesages anymore. They do not deserve to bear our title, our prestige, or our knowledge.\n\nSo many of our teachings lay scattered around this monastery, potentially lost to those of us that remain.\n\nWe must reclaim these writings. Better in my hands than theirs.", progress = "I will not stand for my people's research to be used for evil.", completion = "It's a relief to know that this research is free from those who would abuse it.", objectives = "Collect 5 Tomes of Tidesage Research in Stormsong Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52189] = { id = 52189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forfeit Souls", description = "The tidesages here have given in to dark magics. They have submitted themselves to powers they do not understand, and my people have suffered for it.\n\nI knew them once, my brothers and sisters in the tides. But now they are lost.\n\nI guess I am too.\n\nRedeem the name of the tidesages! Kill these betrayers!", completion = "It didn't feel good to ask that of you, {name}. But it was right.", objectives = "Kill 8 Tidesage Archvists or Tidesage Summoners in Stormsong Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52190] = { id = 52190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining the Upper Hand", description = "We need to retrieve the Abyssal Scepter and get out of here before the Kul Tirans break our line in Plunder Harbor.\n\nI did some research while you were gone. I believe I uncovered the location where the ritual must take place.\n\nWhen you are ready to go, we can make our way over.", progress = "Nathanos and I believe scepter will help us gain the upper hand on the Kul Tiran fleet. If you wish to win this war, the Abyssal Scepter is key.", completion = "We've got the scepter... for better or for worse.", objectives = "Aid Zelling in retrieving the Abyssal Scepter from Stormsong Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52191] = { id = 52191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life Held Hostage", description = "As Lilian has pointed out, it seems we have a final visitor.\n\nShall we go pay him a visit?", progress = "There is nothing left for us here. Let us return.", completion = "We have the scepter, we maintain our possession of Derek's corpse...\n\nLet us return to somewhere a little more... homey.", objectives = "Help Nathanos Blightcaller with the last of Proudmoore's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52192] = { id = 52192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aid of the Tides", description = "With Derek's body and the Abyssal Scepter in stow, our undertaking here today is complete. Let us escape under their noses.\n\nWhen you are ready, let us return to Zuldazar. Sylvanas will want to hear of our victories.", completion = "A couple more Kul Tiran ships on the bottom of the ocean wraps up our mission quite well.", objectives = "Talk to Nathanos Blightcaller and return to Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52194] = { id = 52194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What You May Regret", description = "{name}, Genn Greymane left this letter for you. He indicated it was urgent. I was just about to send for you.\n\n<Upon opening it, the letter reads as follows.>\n\"{name},\n\nYou have helped to unite the Kul Tirans and gained their support for the Alliance. Perhaps now you might be able to help reunite a mother with her daughter.\n\nMeet me at the family memorial by Proudmoore Keep. With luck we can convince Lord Admiral Proudmoore to grant her daughter a stay of execution.\n\n- Genn Greymane \"", progress = "My daughter... My Jaina...", completion = "<Katherine looks away for a moment.>\n\nPriscilla- Lady Ashvane convinced me to exile my daughter. I now see she acted in her own self interest, and I do not know if my daughter still lives.", objectives = "Meet with Genn Greymane at the memorial by Proudmoore Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52196] = { id = 52196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandswept Bones" }
quests[52197] = { id = 52197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Long Away", description = "For every foe we slay, two more take their place.\n\nWe are too few in number to stand toe to toe. We must fall back, {name}. Strategy can yet overcome numbers. \n\nWe will regroup at Darnassus. I will send for Delaryn.", completion = "These are troubling times, {name}. We must gather our strength.", objectives = "Regroup with Malfurion and Delaryn at Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52198] = { id = 52198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank and Spank" }
quests[52199] = { id = 52199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rum- Paaaage!" }
quests[52200] = { id = 52200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turtle Tactics" }
quests[52203] = { id = 52203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Paper Trail", description = "The High Commander's intelligence was confident that Trade Prince Gallywix is currently in Zuldazar, but my trackers could not locate him within the Bilgewater camp. He's most likely somewhere nearby.\n\nGoblins do not work for free. Someone is bound to be bossing around the rest of those miners. Locate whoever is in charge, eliminate them, and search for anything that might tell us where Gallywix is.", progress = "Did you find anything useful?", completion = "<Magister Umbric reads the orders you hand him and smiles.>\n\nGallywix is close!", objectives = "Collect Orders From Gallywix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52204] = { id = 52204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Void Solution", description = "The Bilgewater Cartel are serious about protecting their investment at the mining site. My trackers have reported a heavy presence of large mech suits used for breaking rocks and suppressing attackers.\n\nI am certain that you could deal with the mechs yourself, but you need not waste your time doing so.\n\nTake this void shard and use it to cast the large mechs into the Void, where they won't be able to bother anyone again.", completion = "The power of the Void is endless, {name}, if you can control it.", objectives = "Use Magister Umbric's Void Shard to destroy 4 Bilgewater Frackers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52205] = { id = 52205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilgewater Bonanza Go Boom", description = "I have met very few goblins that I respect, but I must give them universal credit for one thing: they are persistent.\n\nThe Bilgewater Cartel, Trade Prince Gallywix's gang, has already sent a full set of replacement miners to extract Azerite from the beach site nearby.\n\nI am certain the Alliance will be pleased if you interrupt their mining operations again.\n\nMy regiment is available to aid you, but our combat tactics are unconventional. When you wish our help, call into the Void and we will answer.", completion = "I do not doubt that those goblins will be replaced, like the ones you previously dealt with.\n\nBut we have at least set back their progress and given our allies here additional breathing room.", objectives = "Kill 12 Bilgewater goblins and open Void Tears to summon void elf allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52207] = { id = 52207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azerite Stuff" }
quests[52208] = { id = 52208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting of the Minds", description = "We're in luck. The missive details a meeting in Zo'bal Ruins between Talanji, Rokhan, Areiel, and Blood Prince Dreven.\n\nThis is our chance to gain more intel on Dreven and his next move. He killed our soldiers in Vol'dun, it's time for him to pay.\n\nMeet me outside of Zo'bal Ruins. We're going to sneak into the ruins, listen to their plans, and decide what to do next.", progress = "Let's move.", completion = "Dreven will be inside of an enclosed tunnel? This is too perfect. Let's move.", objectives = "Meet Shandris Feathermoon outside of Zo'bal Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52209] = { id = 52209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turtle Tactics" }
quests[52210] = { id = 52210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sending Out An SOS", description = "I noticed an exodus from the fleet, far out in the harbor.\n\nFlyers were sent out, they seek something, or someone.\n\nThose ships made a great journey, and they have much work ahead.\n\nPlease check in with Captain Grez'ko. I am sure he could use a hand!", completion = "You're just de mon I was looking for! I have heard tales.", objectives = "Speak to the Captain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52211] = { id = 52211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Sunrise" }
quests[52212] = { id = 52212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Stromgarde" }
quests[52213] = { id = 52213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Skinning Knife", description = "Within the scarred flesh of the beast, you find a notched golden blade embedded under its skin.\n\nCarefully extracting the blade, you can't help but feel like this is an old Zandalari skinning knife.\n\nYou should show this to Rana the Cutta.", completion = "Ha ha! If I did not know better, I  would say dis was de skinning knife of my old master.\n\nHe went out to collect some pelts a couple years ago, and never came back. I figured de idiot got crushed by a log.\n\nIf dis was in it's skin, he must have thought he killed it, only to have it wake up and finish him off.\n\nI needed dat laugh. Thank you for dat. Lemme make it up to you.\n\n<Continuing to chuckle to herself, she uses her master's knife to show you a trick to harvesting leather from a kill.>", objectives = "Return the Ancient Skinning Knife to Rana the Cutta.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52214] = { id = 52214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ceremonial Vestments", description = "Xanjo asked dat I gather de materials for him to make some ceremonial armor.\n\nHe requested several pieces of crocolisk hide, but all de hides I have are flawed or scarred.\n\nI need you to bring me a handful of fresh crocolisk hides dat are pristine.\n\nDe best source dat I know of are de primal snapjaws in Nazmir, as their hide is usually thick enough to avoid getting scarred when dey fight.\n\nIf you do dat for me, I will show you how to better harvest scales from, well... scaly creatures.", progress = "Have you got de skins?", completion = "Excellent!\n\nDese are good! Well, usable... for de most part.\n\nI will need to clean dem up before I can pass dem along. Regardless, look here and I will show you how to get more out of skinning things with scales.\n\n<Rana uses the skins you brought to exemplify small tweaks to be made to your technique to yield better results.>", objectives = "Collect 3 Pristine Skins from Primal Snapjaws in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52215] = { id = 52215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thicker Thread", description = "{name}! I was hoping you would show up!\n\nXanjo is nearly finished with de suit of ceremonial armor he has been working on, but dere is a problem.\n\nHe says dat de thread he used is too thin, and dat de weight of de leather is ripping out de stitching.\n\nHe asked me to get something dat will hold, and de best thing I can think of is de thick webbing of jungleweb crawlers.\n\nYou can find dem in northern Vol'dun. Bring me back some strands of their thick webbing, and my knowledge of scales is yours.", progress = "So, did you get de silk?", completion = "Yes, dis should do nicely.  Once de thread is replaced with dis webbing, dat armor is never going to fall apart!\n\nAlthough... dis is stickier dan I was expecting. I will have to ask Xanjo if dat is going to be a problem.\n\nBut first, your lesson. Learn quickly, my pupil.\n\n<Rana picks up a skin covered in scales, and shows you how to more effectively remove the skin without damaging the scales.>", objectives = "Loot 5 Strands of Thick Webbing from Jungleweb Crawlers in Vol'Dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52216] = { id = 52216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexoskeleton", description = "I have a bet going with Xanjo over what leather is de best for armor in regards to resisting piercing and slashing attacks.\n\nHe says scales are the best, but I have something better in mind.\n\nI feel de makrura's exoskeleton could be treated to act as a natural plate armor.\n\nBring me de carapace of a bittertide makrura, and I will teach you how to harvest bones more effectively from creatures you're skinning.", progress = "Do you have de carapace?", completion = "Nice.\n\nThese plates are very thick, and TECHNICALLY leather. My victory is almost guaranteed.\n\nAs for your lesson... makrura don't have bones.\n\n<Rana smiles.>\n\nFine, fine! I will teach you something useful, too.\n\n<Putting the carapace on the ground, Rana shows you how to feel if a bone is broken before removing it.>", objectives = "Collect an Unbroken Makrura Carapace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52217] = { id = 52217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa Fit For A King", description = "Hey, {name}! Come here. Shh. Closer.\n\n<Rana's voice drops to a whisper.>\n\nI have something I want you to do for me. It may be just a touch sacreligous, but... well...\n\nRezan was once de loa of kings, but he has been taken to Atal'Dazar, and it grieves me what has happened to him.\n\nI want you to go dere, and bring me back a bone of his. Not even a whole bone. A splinter. I don't care how small.\n\nPlease do dis for me, and I will teach you everything I know about gathering bones while skinning.", progress = "Did you get it?", completion = "<Rana begins speaking in a whisper and places the bone fragment in a small pouch of a necklace she is wearing.>\n\nDis means a lot to me. \n\nWhile I will never be a king, I will have de Loa of Kings watching over me for de rest of my days.\n\n<Rana dusts off her hands as she returns to her normal volume.>\n\nIf I recall correctly, I promised to teach you everything  I know about gathering bones, yes?\n\n<Rana begins explaining which bones can be easily removed from the socket without breaking the bones.>", objectives = "Collect Rezan's Bone Fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52218] = { id = 52218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Horrors", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52219] = { id = 52219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Blood Prince Dreven", description = "We must kill Blood Prince Dreven and his followers. I know of the place where they intend to go. Here is the plan.\n\nYou and Keeshan will make your way to the tunnels and act as bait, lure Dreven into a false sense of security.\n\nMyself and the sentinels will seal the entrance to trap him and his allies shortly thereafter.\n\nThen we kill them all. I'll send word to the others to get moving.\n\nLet's go.", completion = "Keeshan has recovered, and I've sent scouts to retrieve the bodies of my sentinels.\n\nThey died fighting a monster. Keeshan and I will give them the highest honors.\n\nI'll send a report to Halford regarding what happened here. We must make the destruction of Draven our highest priority.\n\nThank you for all your help, {name}. We could not have done this without you.", objectives = "Meet Keeshan within the Collapsed Tunnels in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52221] = { id = 52221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Stonefist Watch", description = "Your followers have sent a report regarding the assault on Stonefist Watch.\n\nIt details that victory was hard-fought, but all of the bandits previously living in the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission to Tiragarde Sound?", completion = "It seems the mission to create an additional foothold in Tiragarde Sound was a success. Well done, {name}.\n\nI will send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52222] = { id = 52222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonefist Watch", description = "The raid you planned for Stonefist Watch in Tiragarde Sound was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Stonefist Watch in Tiragarde Sound and establish fortifications there.\n\nStonefist Watch will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", completion = "Throm-Ka, {name}. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Tiragarde Sound!", objectives = "Claim Stonefist Watch for the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52223] = { id = 52223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brinepinch", description = "You! {name}! I have a business proposition for you.\n\nThere is a monstrous crab nesting in some of my favorite hunting grounds.\n\nI've already been forced out of some areas because of the sirens, I'm not about to lose more to a CRAB!\n\nBring me the head of Brinepinch! In return I'll teach you how to get more leather when skinning.\n\n<Camilla pauses for a second before clarifying her thought.>\n\nSorry, most creatures that wrong me have heads. Just bring me some part of it as proof of its death.", progress = "Have you slain the beast yet?", completion = "Excellent! I'll have to celebrate by going hunting later today.\n\nAs for you, {name}, allow me to show you a technique you've probably never seen before...", objectives = "Kill Brinepinch, and bring its \"head\" to Camilla Darksky.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52224] = { id = 52224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivory Handled Dagger", description = "While skinning the beast, you feel a lump within the beast's stomach.\n\nInvestigating further, you find what appears to be a dagger with a beautifully etched ivory handle.\n\nCarefully extracting it, you wonder if Camilla Darksky might know something about this.", completion = "I wondered what happened to him...\n\nYes, I recognize the blade. It was my mentor's.\n\nWe sailed here together, but later he went missing. He talked about building a home in Drustvar overlooking the ocean, so I figured that's what happened.\n\nBut I guess he was eaten by the creature... in which case, I'm thankful you avenged him by slaying it.\n\nAs a thank you for this closure, let me show you his secret to skinning.\n\n<Camilla takes out a fresh pelt and begins showcasing her lost mentor's technique.>", objectives = "Return the Ivory Handled Dagger to Camilla Darksky.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52225] = { id = 52225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Pursuit of Fashion", description = "Despite me REPEATEDLY stating that I'm not a leatherworker, one of the fat nobles of this city has commissioned me to make him a belt of 'the finest saurolisk' hide.\n\nSo... I'm just going to get the materials together, give them and some of the gold to Cassandra to make the actual belt, and pocket the difference.\n\nThat said, I need you to bring me saurolisk leather, enough to circle a very wide lord.\n\nFor your efforts, I'll look at the skins and see if I can give you pointers on how to harvest more.", progress = "Have ya got the hides?\n\nMy employer is becoming... incessant.", completion = "<Camilla takes a moment to look over the hides.>\n\nAcceptable work. We'll lose some material trimming, but there should be enough to encompass our esteemed and honorable benefactor.\n\nAlso, I think I see an error that, if corrected, could help when you're harvesting from anything with scales. Show me what you did.\n\n<Camilla hands you a knife and watches your movements as you explain. She occasionally stops you to adjust the position of your hands and states that it'll help next time.>", objectives = "Loot 3 Pristine Saurolisk Skins from Shallows Saurolisks in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52226] = { id = 52226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turtle Soup", description = "I cannot believe that I'm constantly stuck in this city!\n\nYou'd help me out, right?\n\nYou see, I've heard about these turtles that have been living in hot springs.\n\nWhat makes it interesting is that some of the sulphur from the water has soaked into their scales to give them interesting patterns.\n\nI'm too busy to go check myself, but if you could go get me some of their skins, I'd be more than willing to teach you everything else I know about skinning anything with scales in exchange.", progress = "Please tell me you've got the skins.", completion = "Wow, these are... underwhelming.\n\nFrom they way they were described, I figured they would be irridescent or something.\n\nInstead, they're just yellow and smell of farts.\n\nRegardless, you've kept me from losing my sanity for one more day.\n\n<Camilla deftly draws her skinning knife and begins weaving it along and between scales.\n\nWhile her finesse may be without equal, you feel the demonstration is more than enough to ensure you can harvest more scales.>", objectives = "Loot 5 Sulphur Speckled Skins from Enriched Rockshells.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52227] = { id = 52227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bone Needle", description = "<You see Camilla sucking blood from a wound on her hand.>\n\nHey, can you do me a favor? I was sewing shut a battle wound in this skin, when my last bone needle broke, and now I need to get a new one.\n\nI've seen quilrats on the coast of Drustvar, one of their spines should do the trick.\n\nBring me one in perfect condition, and I'll teach you how to harvest more bones when skinning.\n\n<Camilla looks at her hand.>\n\nNow, if you'll excuse me, I need to go see a healer before this gets infected.", progress = "I've got a lot of work backed up, waiting on a new needle.\n\nHave you got it yet?", completion = "Let's see... smooth, strong, sharp... Ow!  Very sharp!\n\nYeah, I think this'll do nicely.  Good job!\n\n<Camilla picks up a skin and starts mending another hole in the skin that looks like it's from combat. \n\nHappy with the result, she turns to you and starts explaining how to extract additional bones when skinning.>", objectives = "Collect an Immaculate Quill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52228] = { id = 52228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: An Unbreakable Bone Needle", description = "Hey, {name}, lookin' for work?\n\nI've heard through Alliance Intelligence that the trolls have a dead god or something similar. 'Rezan' I think was the name, over in Atal'Dazar.\n\nAfter the last time I broke a bone needle, I can't help but think that one made from the bone of a god has got to be indestructible, right?\n\nI want you to retrieve one of his bones. Or at least something big enough that I can carve an eye in and use.\n\nIn return, I'll show you everything that I know about harvesting bones.", progress = "I hope this works. Going the rest of my life without needing to replace that damn needle...\n\nHave ya got it?", completion = "Good! This is the perfect size for some of the smaller, more delicate work, the kind that would break needles constantly.\n\nAre you ready for your lesson?\n\n<Camilla spends the next several minutes showing you how to dislocate and quickly flay bones that were previously too time consuming to bother trying to collect.>", objectives = "Travel to Atal'Dazar and collect Rezan's Bone Fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52229] = { id = 52229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Much To Bear" }
quests[52230] = { id = 52230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loose Change" }
quests[52234] = { id = 52234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Amongst the Leaves", description = "When the Horde invaded, I did my best to thwart them but it is unknown how many forces have made passage already. This wall will slow them down, but it will not halt their attack entirely. \n\n<Malfurion's ears perk.>\n\nDo you hear that, hero? The Ancients call to us!\n\nWe must protect them at all costs, {name}! They see what our eyes cannot see, and hear what our ears cannot perceive.\n\nI have druids in the Twilight Vale. Find them. Send them to the Grove of the Ancients. I will reinforce the wall.", completion = "Elune be praised!", objectives = "Find 8 hidden Druids of the Claw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52236] = { id = 52236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thorny Problem" }
quests[52237] = { id = 52237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Underrot: Restless Horror" }
quests[52238] = { id = 52238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Underrot: Mysterious Spores" }
quests[52239] = { id = 52239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loose Change" }
quests[52240] = { id = 52240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garden Grove", description = "Curse those goblins and their infernal machines!\n\nThey are using a shredder to desecrate our sacred grove. \n\nWe need that monstrosity taken down!", completion = "Well done. These trees have so many stories to tell.", objectives = "Defeat the Monstrous Shredder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52241] = { id = 52241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Greedy Goblin's Paradise", description = "The Zandalari have many powerful and ancient artifacts tucked away on this island, hidden from view.\n\nBut some of their treasures are more... conspicuous.\n\nIt is no surprise that Trade Prince Gallywix was unable to resist the allure of Atal'Dazar, a massive city made entirely of gold.\n\nCome with me and we will hunt him down together.", completion = "Gallywix has no respect for culture or history. Only money.", objectives = "Use the Magister Umbric's Void Portal to join him in Atal'Dazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52242] = { id = 52242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wake of Something New", description = "<Onu bellows in pain.>\n\nThe disturbance has become more severe. I am sensing a powerful force in our midst. It is unlike anything I have felt before. It comes from the earth itself.\n\nYou and Delaryn Summermoon must seek it out, {name}. Go to the water's edge, to the place you call Nazj'vel.", progress = "Keep your head down!", completion = "The Horde have taken the Master's Glaive! \n\nWe thought the glow from this place was Elune's light... but it appears to be the Azerite the Horde so desperately desire.", objectives = "Find the source of Onu's pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52243] = { id = 52243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel for the Demolishers" }
quests[52244] = { id = 52244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Drilling" }
quests[52245] = { id = 52245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Furbolgs", description = "The ancients of the forest are all connected to one another. We can sense a disturbance from deep within our roots. \n\nI can feel it now, {name}... the rumble of their footsteps in the distance, the thundering clamor of war. With every branch they break, they awaken the ancients.\n\nSoon my brethren will answer in kind, for nothing shall disrupt the balance of nature. \n\nA disturbance is near. Our kindred spirits cry for help. Seek it out and restore balance.", completion = "Have the furbolgs been returned to the wild?", objectives = "Find those who cry for help within the Blackwood Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52246] = { id = 52246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Shipment", description = "I let grief cloud my judgment and Jaina may have already paid the ultimate price for my mistake. Yet, I hold out hope she lives.\n\nI do not know where Jaina was taken after Ashvane's people took her from the Keep. The records in their offices here in Boralus will surely tell you where they took her.\n\n{name}, you helped my people when I thought I did not need it. I ask for your help again now. Save my daughter's life!", progress = "Did you find what happened to Jaina?", completion = "<Katherine looks up, resolved.>\n\nWe have little to go on, but I must believe she still lives.", objectives = "Search the Ashvane Offices for information on where Jaina was taken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52247] = { id = 52247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Gallywix", description = "Look at this... The goblins are looting ancient ornamentation like they're hoarding food at a buffet. What a disgrace.\n\nBut we do not have time to get bogged down in everything happening here. Gallywix will soon know that we have arrived.\n\nWe should not hesitate in ascending these stairs and locating Gallywix. I am certain that he will be wherever the thieves are carrying their treasure.\n\nOh, and please do take care. The Zandalari do not typically leave places like this unguarded.", progress = "Gallywix's greed will be his undoing.", completion = "A \"pleasure palace?\" What sort of selfish leader fritters away his people's lives and fortunes in this way?", objectives = "Find and chase Trade Prince Gallywix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52248] = { id = 52248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shores of Xibala" }
quests[52249] = { id = 52249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shores of Xibala" }
quests[52250] = { id = 52250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Xibala" }
quests[52251] = { id = 52251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compromised Reconnaissance" }
quests[52252] = { id = 52252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Explosive Entrance", description = "A hat and some smooth talking won't get us in to Freehold this time, so I'm thinking explosives. And I'm thinking we steal them from Ashvane. Fair's fair, right? She takes something from Lady Katherine, we take some Azerite empowered grenades from Ashvane.\n\nOkay, so it's not really the same, but you get where I'm going with this.\n\nHead over to Ashvane's Foundry. Grab the biggest Azerite Grenades you can get your hands on.\n\nWhile you do that I'm going to get us some air support.", progress = "Nicely done! These are going to make quite an impact, if you'll forgive the pun.", completion = "You got our ammo and I got our air support.\n\n<Flynn gestures to Taelia and Galeheart with a grin.>\n\nYou see where I'm going with this.", objectives = "Collect 100 Large Azerite Grenades from the Ashvane Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52253] = { id = 52253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keys to Success in Freehold", description = "I've been known to be a betting man, and I'd place good odds on the information we need being in Harlan Sweete's Strongbox. This would be far too valuable to put anywhere else. I bet they haven't even moved the chest. The problem is the security features.\n\nSee, the chest is locked by three keys and he gave each one to a different lieutenant. We'll need to get those.\n\nBut between your skills, my finesse and Taelia's air support this will be easy.", progress = "Nicely done! See? I knew those Irontide wouldn't be a problem for you.", completion = "Okay, we have the keys. Now we just need to make a run for the chest.", objectives = "Collect the keys from Irontide Lieutenants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52256] = { id = 52256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion Returns", description = "Do you hear his voice?\n\nMalfurion seeks our aid! Keep your head high, {name}. The ancients stand with you this day.", completion = "We must push them back!", objectives = "Find Malfurion at the Wildbend River.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52257] = { id = 52257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Rock\" The World", description = "We do not fight alone, {name}.\n\nThis day, the ancients will bear you in their branches. Hold back nothing in your defense of our forests!", progress = "We must hold them back!", completion = "We must hold them back!", objectives = "Join the Ancients to slay Horde enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52258] = { id = 52258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Sells Seashells", description = "Papa wanted to go fishing, and mum is working, so he brought me along.\n\nBut I'm bored! I'm trying to sell some of the shells I found washed up on the beach, but nobody seems to be stopping. I don't think my shells are pretty enough...\n\nYou don't seem like you're afraid of those big snakes on the beach. Can you bring me back some prettier shells? Only the shiniest please!", progress = "Come, let us parley... How was that? I'm trying to sound like a proper shell seller.", completion = "Oooh! These are so pretty! I bet they'll sell really well.", objectives = "Gather shells for Jenny.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52259] = { id = 52259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Take No Pleasure In This", description = "I knew that Gallywix was selfish and wasteful, but this... this is too much.\n\nHis bloated pride has blacked out the sun of good leadership. He hoards the wealth of his people to satiate his gluttony, greed, and lust while his people toil under his calloused heel.\n\nAnd, maybe worse, opportunistic socialites from all across the Horde revel in the depravity.\n\nAll people of Azeroth deserve better than this. We must teach these spoiled cowards a lesson.", progress = "How can they live like this while their people suffer?", completion = "I won't pretend that this will solve all of the goblins' problems, but it does feel good to bring a little justice to these pompous parasites.", objectives = "Crash Gallywix's party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52260] = { id = 52260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have Him Cornered", description = "Did you hear Gallywix barking orders to his servants and thugs? Still concerned with frivolities as we edge ever closer.\n\nHe feels safe in his petulant palace of profits. He should not.\n\nEven here, we will strike down Trade Prince Gallywix. For the Alliance!", progress = "Gallywix will not be missed.", completion = "The Gallywix that we fought was a decoy? A body double?\n\nInfuriating. We were so close... I'm sorry, {name}.", objectives = "Kill Trade Prince Gallywix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52261] = { id = 52261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gallywix Got Away", description = "I must confess my disappointment that we were not able to bring an end to Gallywix's greedy reign today.\n\nBut I blame no one but myself, and will report the same to the High Commander. Your performance was exemplary, just as I expected.\n\nI hope the Alliance will not lose faith in the void elves because of this. We have much to offer.\n\nWhen you're ready, I will open a final Void portal to take us back to Boralus.", completion = "Thank you, {name}. Not every failed mission is a failure.\n\nWe've put Gallywix on the run and uncovered his decoy operations. And I, personally, also learned a thing or two from the surprising tactics of Umbric's void elf regiment.\n\nI have no doubt that the denizens of the Void will prove valuable to the Alliance in the trying days ahead.", objectives = "Return to High Commander Halford Wyrmbane on the Wind's Redemption in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52271] = { id = 52271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Salt Flavored" }
quests[52275] = { id = 52275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Swiftwind Post", description = "Your followers have sent a report regarding the assault on Swiftwind Post.\n\nIt details that victory was hard-fought, but all of the wicker beasts previously infesting the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission to Drustvar?", completion = "It seems the mission to create an additional foothold in Drustvar was a success. Well done, {name}.\n\nI will send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52276] = { id = 52276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swiftwind Post", description = "The raid you planned for Swiftwind Post in Drustvar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Swiftwind Post in Drustvar and establish fortifications there.\n\nSwiftwind Post will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", completion = "Welcome, {name}. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Drustvar!", objectives = "Claim Swiftwind Post for the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52278] = { id = 52278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rogue Azerite", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52279] = { id = 52279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Looming Threat", description = "If we hope to push the Horde out of our lands, we must call upon all the strength our people have to offer.\n\nGo, seek out the druids, the priestesses, our sentinels! Make the call to arms, and watch as the kaldorei rise to action. Only together can we hope to end the stalemate at the Wildbend River.\n\nWhen you are finished, report to Malfurion Stormrage. He awaits our fleet in Rut'theran Village.", completion = "No matter the odds, we must stay strong.", objectives = "Rally the kaldorei forces in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52280] = { id = 52280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Salt Flavored" }
quests[52281] = { id = 52281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Cover of Swiftwing", description = "Aye! So we be the first in this crazy operation. We'll be hitchin' a ride on Swiftwing to tha Isle of Fangs.\n\nThe Zandalari got one of their main ships there, called the Breath of Pa'ku, whatever that is.\n\nHop on ta Swiftwing when yer ready te go. It's gonna get real cozy on there with all of ye comin' aboard.", progress = "Hop on!", completion = "All we need to do is plant some bombs and cause some chaos without the mainland Zandalari knowing. \n\nEasy, right?", objectives = "Ride Swiftwing to the Isle of Fangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52282] = { id = 52282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Sink a Zandalari Battleship", description = "Let's go over our plan of attack, but remember above all things, the Zandalari cannot know our full forces are here.\n\nIf they were to discover an Alliance base within the shadow of their empire... we would be wiped out in an instant.", progress = "Let's go over the plan.", completion = "You know the plan, {name}. Stay hidden and weaken the Zandalari fleet. If we accomplish those two goals, we'll walk out of here alive.", objectives = "Go over the plan to weaken the Zandalari naval fleet with Halford.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52283] = { id = 52283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotaging the Pa'ku", description = "Our first job is to plant some bombs along these ships. I'll take care of the smaller ships, you deal with the Breath of Pa'ku.\n\nWhatever that means.\n\nKelsey says these bombs are the latest in gnome technology. We plant 'em and she can detonate them at any time.\n\nLet's get moving, and remember, this whole plan works as long as they don't see us plantin' these bombs.", completion = "All the bombs are planted on my end. Still wish we could blow 'em up now. \n\nGuess we'll have to just wait until the time is right to blow these things sky high.", objectives = "Plant 4 Remote-Detonation Deathbombs beneath the Breath of Pa'ku.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52284] = { id = 52284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship Logs", description = "We've got mogu and Zandalari working together on the Breath of Pa'ku. They've got records on the Zandalari fleet's ships.\n\nWe've been making educated guesses regarding the Zandalari fleet. It's time to upgrade our intel.\n\nGo in there and get the naval records from anyone on board that ship.\n\nOh, and take these jet boots. You'll need them to reach the boat if you're planting bombs on the hull.", progress = "Did you get those naval records? We'll need them to better plan against the Zandalari.", completion = "Perfect! I'll get these documents back to Halford. We'll be able to coordinate future attacks with this.", objectives = "Recover 6 Naval Records from Zandalari and Mogu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52285] = { id = 52285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enlarged Miniaturized Submarine", description = "Our next target is a ship docked in a place across from here, the Warport Rastari.\n\nLucky for you, I can get us all there in my enlarged miniaturized submarine.\n\nShandris Feathermoon and Magister Umbric should be waiting for you on the coast of Warport Rastari.\n\nLet's get going!", completion = "Glad you could make it, {name}. We've got a lot to do within Warport Rastari.", objectives = "Ride Kelsey's Enlarged Miniaturized Submarine to Warport Rastari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52286] = { id = 52286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Beneath Their Nose", description = "We must continue with our primary goal, plant bombs on major Zandalari ships. There is one docked within the Warport.\n\nYou know what to do. Get beneath the boat, plant the bombs, and ensure no one sees... a blood troll using bombs.\n\nMy invisibility flask will give you the stealth you need, and Umbric believes the ritual will give you some other power to tap into.", progress = "Good luck, {name}, and stay safe.", completion = "Good work. The Zandalari will be in for a rude awakening when we blow up their flagships moments before our first naval incursion.", objectives = "Plant 3 Remote-Detonation Deathbombs within the main warship in Warport Rastari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52287] = { id = 52287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intelligence Denial", description = "There are three Horde spymasters stationed within Warport Rastari. They are giving the Zandalari information on the Alliance fleet.\n\nWe need these targets killed. We cannot allow the Zandalari to get any advantageous information on our fleet.\n\nLuckily for us, your blood troll disguise means any witnesses will believe this to be a bold attack by the blood trolls.", completion = "You've prevented the zandalari from getting crucial information regarding our naval forces. Well done.", objectives = "Kill Spymaster Stormhorn, Spymaster Bloodsnarl, and Spymaster Bilespreader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52288] = { id = 52288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Vacation", description = "The Horde have sent emissaries to help with their potential alliance with the Zandalari. \n\nThese emissaries are also sharing secrets that the Horde have regarding the Alliance. We need to put a stop to this.\n\nTake this orb. It will create a void portal above the target and pull them... somewhere else.", completion = "Good work, this should cripple both the Horde and the Zandalari in their fight against the Alliance.", objectives = "Use the Portal Orb on 6 Horde Emissaries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52289] = { id = 52289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory is Assured", description = "Our task is finished. You've planted the bombs on two of the Zandalari's major flagships, and Keeshan has helped with the remainder.\n\nLet's return to Halford, the sooner we're done here, the better. It's far too risky for us to be at the Zandalari's doorstep.", completion = "{name}, good timing. We have to move.\n\nWe've been discovered.", objectives = "Meet Halford Wyrmbane at Xibala in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
